#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <cctype>
#include <string>
using namespace std;

const int MAXN = 2000;
const int MAXG = 12;
const int INF = 1000000000;

int dist[MAXG][MAXG];
int gridA[MAXG][MAXG];
int gridB[MAXG][MAXG];
vector<int> adj[MAXN];
vector<int> exitList[MAXG][MAXG];

int dRow[4] = {0, -1, 0, 1};
int dCol[4] = {1, 0, -1, 0};

struct Matching {
    int leftMatch[MAXN], rightMatch[MAXN];
    bool visited[MAXN];
    int matchedCount;

    int compute(int n, vector<int> adjList[]) {
        matchedCount = 0;
        fill(leftMatch, leftMatch + n, -1);
        fill(rightMatch, rightMatch + MAXN, -1);
        for (int u = 0; u < n; ++u) {
            fill(visited, visited + MAXN, false);
            if (augment(u, adjList)) ++matchedCount;
        }
        return matchedCount;
    }

private:
    bool augment(int u, vector<int> adjList[]) {
        for (int v : adjList[u]) {
            if (visited[v]) continue;
            visited[v] = true;
            if (rightMatch[v] == -1 || augment(rightMatch[v], adjList)) {
                leftMatch[u] = v;
                rightMatch[v] = u;
                return true;
            }
        }
        return false;
    }
};

void bfsFrom(int sr, int sc) {
    queue<pair<int, int>> q;
    fill(&dist[0][0], &dist[0][0] + MAXG * MAXG, -1);
    q.emplace(sr, sc);
    dist[sr][sc] = 0;
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (int i = 0; i < 4; ++i) {
            int nr = r + dRow[i], nc = c + dCol[i];
            if (nr >= 0 && nr < MAXG && nc >= 0 && nc < MAXG &&
                gridA[nr][nc] >= 0 && dist[nr][nc] == -1) {
                dist[nr][nc] = dist[r][c] + 1;
                q.emplace(nr, nc);
            }
        }
    }
}

void expandFrom(int sr, int sc, int cnt, int T, int &nodeIdx) {
    int vis[MAXG][MAXG];
    queue<pair<int, int>> q;
    fill(&vis[0][0], &vis[0][0] + MAXG * MAXG, -1);
    q.emplace(sr, sc);
    vis[sr][sc] = 0;
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        if (vis[r][c] > min(T, dist[r][c])) continue;
        for (int e : exitList[r][c]) {
            for (int k = 0; k < cnt; ++k) {
                adj[nodeIdx + k].push_back(e);
            }
        }
        if (vis[r][c] == min(T, dist[r][c])) continue;
        for (int i = 0; i < 4; ++i) {
            int nr = r + dRow[i], nc = c + dCol[i];
            if (nr >= 0 && nr < MAXG && nc >= 0 && nc < MAXG &&
                gridA[nr][nc] >= 0 && vis[nr][nc] == -1) {
                vis[nr][nc] = vis[r][c] + 1;
                q.emplace(nr, nc);
            }
        }
    }
    nodeIdx += cnt;
}

int main() {
    int n, T;
    cin >> n >> T;
    fill(&gridA[0][0], &gridA[0][0] + MAXG * MAXG, -1);
    fill(&gridB[0][0], &gridB[0][0] + MAXG * MAXG, -1);
    int startR = -1, startC = -1;

    string line;
    for (int i = 1; i <= n; ++i) {
        getline(cin, line);
        for (int j = 1; j <= n; ++j) {
            char c = cin.get();
            if (isdigit(c)) gridA[i][j] = c - '0';
            if (c == 'Z') { startR = i; startC = j; }
        }
    }
    cin.ignore();

    bfsFrom(startR, startC);

    for (int i = 1; i <= n; ++i) {
        getline(cin, line);
        for (int j = 1; j <= n; ++j) {
            char c = cin.get();
            if (isdigit(c)) gridB[i][j] = c - '0';
            for (int k = 0; k < gridB[i][j]; ++k) {
                exitList[i][j].push_back((int)exitList[i][j].size());
            }
        }
    }
    cin.ignore();

    for (int i = 0; i < MAXG; ++i)
        for (int j = 0; j < MAXG; ++j)
            if (dist[i][j] == -1) dist[i][j] = INF;

    int nodeCount = 0;
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (gridA[i][j] > 0) expandFrom(i, j, gridA[i][j], T, nodeCount);

    Matching solver;
    cout << solver.compute(nodeCount, adj) << '\n';
}
